using UnityEngine;

// 보스 AI · 그림자 슬라임 왕
// 「패턴 고르기 → 경고 표시(텔레그래프) → 공격 → 잠깐 쉬기」를 되풀이하는 상태 머신이에요.
//   내려찍기: 주인공 발밑에 빨간 원이 차오르고, 다 차는 순간 원 안에 있으면 피해
//   돌진   : 보스 앞에 빨간 띠가 깔리고, 잠시 뒤 그 길을 따라 빠르게 돌진
//   탄막   : 보라 구슬을 사방으로 발사 (2페이즈에는 엇갈려서 두 번)
//   바닥 폭발: 3×3칸 경고 발판이 깔리고 깜빡이다가 터짐 (첫 발판은 주인공 발밑 · 2페이즈에는 더 많이)
// 체력이 절반 이하가 되면 2페이즈: 경고가 짧아지고, 내려찍기를 세 번 연달아 하고, 「분노 볼륨」이 켜져요.
// 주인공의 공격(HeroCombat의 hero.Attack)이 닿으면 엔진이 OnHit()을 불러 체력이 줄어요.
// H 키: 히트박스 보기 (보스 몸통 · 주인공 몸의 판정 범위)
// 좌표 단위는 칸, 오른쪽이 +x · 아래쪽이 +y 예요.
public class BossAI : MonoBehaviour
{
    [Header("체력")]
    public int maxHp = 30;

    [Header("내려찍기")]
    [Tooltip("빨간 원의 반지름 (칸)")]
    public float slamRadius = 1.5f;
    [Tooltip("원이 다 차오르기까지 걸리는 시간 (초) · 피할 시간")]
    public float slamWarn = 1.1f;
    public int slamDamage = 20;

    [Header("돌진")]
    public float dashLength = 7f;
    public float dashWarn = 0.9f;
    [Tooltip("1초에 움직이는 칸 수")]
    public float dashSpeed = 12f;
    public int dashDamage = 25;

    [Header("탄막")]
    [Tooltip("한 번에 쏘는 구슬 수 (씬에 「구슬 1」~「구슬 16」이 있어요)")]
    public int orbCount = 8;
    public float orbSpeed = 4f;
    public float orbLife = 2.6f;
    public int orbDamage = 12;

    [Header("바닥 폭발 (경고 발판)")]
    [Tooltip("한 번에 까는 발판 수 (2페이즈 +3 · 씬에 「경고 발판 1」~「경고 발판 9」가 있어요)")]
    public int panelCount = 5;
    public float panelWarn = 1.3f;
    public int panelDamage = 18;

    [Header("몸통 · 쉬기")]
    [Tooltip("이 거리(칸)보다 가까우면 몸통에 닿은 것")]
    public float bodyRadius = 1.0f;
    public int touchDamage = 10;
    public float restTime = 1.3f;
    public float startDelay = 2.2f;

    [Header("무대 (보스가 움직일 수 있는 범위)")]
    public float minX = 2f;
    public float maxX = 17f;
    public float minY = 3f;
    public float maxY = 10f;

    private int hp;
    private int phase = 1;
    private int state = 0;      // 0 등장 · 1 쉬기 · 2 내려찍기 · 3 돌진 경고 · 4 돌진 · 5 탄막 · 6 쓰러짐 · 7 바닥 폭발
    private int panelUsed = 0;
    private float timer = 0f;
    private int lastPattern = -1;
    private int slamLeft = 0;
    private Vector2 target;
    private Vector2 dashDir;
    private float dashMoved = 0f;
    private Vector2 orbStartA;
    private Vector2 orbStartB;
    private float orbAge = 0f;
    private bool waveB = false;
    private float flashTimer = 0f;
    private float hurtFlash = 0f;
    private float shakeTimer = 0f;
    private int lastHeroHp = 100;
    private bool showHitbox = false;
    private bool winShown = false;
    private float size = 2.5f;
    private Vector2 camHome;

    private Hero hero;
    private GameObject warnRing;
    private GameObject warnFill;
    private GameObject warnLine;
    private GameObject flash;
    private GameObject bodyBox;
    private GameObject heroBox;
    private Volume rageVolume;
    private Volume hurtVolume;
    private Volume winVolume;

    void Start()
    {
        hero = Hero.main;
        warnRing = GameObject.Find("경고 원");
        warnFill = GameObject.Find("경고 채움");
        warnLine = GameObject.Find("돌진 경고");
        flash = GameObject.Find("보스 번쩍");
        bodyBox = GameObject.Find("보스 히트박스");
        heroBox = GameObject.Find("주인공 히트박스");
        rageVolume = GameObject.Find("분노 볼륨").GetComponent<Volume>();
        hurtVolume = GameObject.Find("피격 볼륨").GetComponent<Volume>();
        winVolume = GameObject.Find("승리 볼륨").GetComponent<Volume>();
        rageVolume.weight = 0f;
        hurtVolume.weight = 0f;
        winVolume.weight = 0f;

        camHome = Camera.main.transform.position;   // 제단 전체를 비추는 고정 카메라
        hp = maxHp;
        lastHeroHp = hero.hp;
        timer = startDelay;
        HideWarnings();
        HideOrbs();
        UIScreen.SetText("보스 UI", "페이즈", "1 페이즈");
        UIScreen.Hide("보스 UI");                   // 씬 제목이 사라진 뒤에 보여 줘요
        Message.Show("그림자 슬라임 왕이 깨어난다…", startDelay);
        UpdateBar();
    }

    void Update()
    {
        Effects();
        if (state == 6)
        {
            DeathUpdate();
            return;
        }
        if (hero.isDead)
        {
            HideWarnings();
            return;
        }
        if (phase == 1 && hp <= maxHp / 2)
        {
            EnterPhase2();
        }

        // 몸통에 닿으면 피해 (주인공은 맞은 뒤 잠깐 무적이라 연달아 맞지 않아요)
        if (state != 0 && Vector2.Distance(transform.position, hero.position) < bodyRadius)
        {
            hero.TakeDamage(touchDamage);
        }

        timer -= Time.deltaTime;
        if (state == 0 || state == 1)
        {
            if (state == 1)
            {
                Approach();
            }
            if (timer <= 0f)
            {
                NextPattern();
            }
        }
        else if (state == 2)
        {
            SlamUpdate();
        }
        else if (state == 3)
        {
            if (timer <= 0f)
            {
                state = 4;
                dashMoved = 0f;
                warnLine.SetActive(false);
            }
        }
        else if (state == 4)
        {
            DashUpdate();
        }
        else if (state == 5)
        {
            OrbUpdate();
        }
        else if (state == 7)
        {
            PanelUpdate();
        }
    }

    // ---------- 패턴 고르기 ----------
    void NextPattern()
    {
        if (state == 0)
        {
            UIScreen.Show("보스 UI");               // 등장이 끝나면 체력 바 등장
        }
        int pick = Random.Range(0, 4);
        if (pick == lastPattern)
        {
            pick = (pick + 1) % 4;      // 같은 패턴을 두 번 연달아 하지 않게
        }
        lastPattern = pick;
        if (pick == 0)
        {
            StartSlam();
        }
        else if (pick == 1)
        {
            StartDash();
        }
        else if (pick == 2)
        {
            StartOrbs();
        }
        else
        {
            StartPanels();
        }
    }

    // 2페이즈에는 경고 시간이 30% 짧아져요
    float Warn(float seconds)
    {
        if (phase == 2)
        {
            return seconds * 0.7f;
        }
        return seconds;
    }

    void Rest()
    {
        HideWarnings();
        state = 1;
        timer = phase == 2 ? restTime * 0.7f : restTime;
        UIScreen.SetText("보스 UI", "패턴", "");
    }

    // 쉬는 동안 주인공 쪽으로 천천히 다가가요
    void Approach()
    {
        Vector2 me = transform.position;
        Vector2 toHero = hero.position - me;
        if (toHero.magnitude > 2.5f)
        {
            MoveTo(me + toHero.normalized * 1.4f * Time.deltaTime);
        }
    }

    void MoveTo(Vector2 p)
    {
        transform.position = new Vector2(Mathf.Clamp(p.x, minX, maxX), Mathf.Clamp(p.y, minY, maxY));
    }

    // ---------- 패턴 1 · 내려찍기 ----------
    void StartSlam()
    {
        state = 2;
        slamLeft = phase == 2 ? 3 : 1;
        target = hero.position;
        timer = Warn(slamWarn);
        Callout("⚠ 내려찍기");
    }

    void SlamUpdate()
    {
        float t = 1f - timer / Warn(slamWarn);
        ShowCircle(target, slamRadius, t);
        if (timer > 0f)
        {
            return;
        }
        // 원이 다 찼어요 → 그 순간 원 안에 있으면 맞아요
        Shake(0.25f);
        if (Vector2.Distance(hero.position, target) < slamRadius)
        {
            hero.TakeDamage(slamDamage);
            Debug.Log("내려찍기 명중!");
        }
        slamLeft -= 1;
        if (slamLeft > 0)
        {
            target = hero.position;     // 2페이즈: 주인공이 있는 곳에 한 번 더
            timer = Warn(slamWarn);
        }
        else
        {
            Rest();
        }
    }

    // 원 모양 경고: 테두리(전체 범위) + 안쪽 채움(t가 0 → 1로 차오름)
    // 스프라이트는 아래쪽 가운데를 기준으로 커지므로, 원의 가운데가 pos에 오도록 y를 맞춰요
    void ShowCircle(Vector2 pos, float radius, float t)
    {
        float full = radius * 2f;
        float fill = full * Mathf.Clamp(t, 0.1f, 1f);
        warnRing.SetActive(true);
        warnFill.SetActive(true);
        warnRing.transform.localScale = new Vector3(full, full, 1);
        warnRing.transform.position = new Vector2(pos.x, pos.y - 0.5f + full / 2f);
        warnFill.transform.localScale = new Vector3(fill, fill, 1);
        warnFill.transform.position = new Vector2(pos.x, pos.y - 0.5f + fill / 2f);
    }

    // ---------- 패턴 2 · 돌진 ----------
    void StartDash()
    {
        state = 3;
        Vector2 me = transform.position;
        dashDir = (hero.position - me).normalized;
        if (dashDir.magnitude < 0.5f)
        {
            dashDir = new Vector2(0, 1);
        }
        timer = Warn(dashWarn);
        // 빨간 띠: 길이 dashLength · 가운데 = 보스 + 방향 × (길이 / 2) · 방향만큼 회전
        warnLine.SetActive(true);
        warnLine.transform.localScale = new Vector3(dashLength, 1.2f, 1);
        warnLine.transform.position = me + dashDir * (dashLength / 2f);
        warnLine.transform.eulerAngles = new Vector3(0, 0, Mathf.Atan2(dashDir.y, dashDir.x) * Mathf.Rad2Deg);
        Callout("⚠ 돌진");
    }

    void DashUpdate()
    {
        float step = dashSpeed * Time.deltaTime;
        Vector2 before = transform.position;
        MoveTo(before + dashDir * step);
        dashMoved += step;
        Vector2 now = transform.position;
        if (Vector2.Distance(now, hero.position) < bodyRadius + 0.3f)
        {
            if (hero.TakeDamage(dashDamage))
            {
                Debug.Log("돌진 명중!");
            }
        }
        // 다 달렸거나 무대 끝에 막히면 멈춰요
        if (dashMoved >= dashLength || Vector2.Distance(now, before) < step * 0.5f)
        {
            Shake(0.2f);
            Rest();
        }
    }

    // ---------- 패턴 3 · 탄막 ----------
    void StartOrbs()
    {
        state = 5;
        orbAge = 0f;
        waveB = false;
        orbStartA = transform.position;
        ShowOrbs(1);
        Callout("⚠ 탄막");
    }

    void ShowOrbs(int first)
    {
        for (int i = first; i < first + orbCount; i++)
        {
            GameObject orb = GameObject.Find("구슬 " + i);
            orb.SetActive(true);
            orb.transform.position = transform.position;
        }
    }

    void OrbUpdate()
    {
        orbAge += Time.deltaTime;
        MoveWave(1, orbStartA, orbAge, 0f);
        // 2페이즈: 0.6초 뒤 반 칸씩 엇갈린 두 번째 탄막
        if (phase == 2 && !waveB && orbAge > 0.6f)
        {
            waveB = true;
            orbStartB = transform.position;
            ShowOrbs(orbCount + 1);
        }
        if (waveB)
        {
            MoveWave(orbCount + 1, orbStartB, orbAge - 0.6f, Mathf.PI / orbCount);
        }
        if (orbAge > orbLife + (waveB ? 0.6f : 0f))
        {
            HideOrbs();
            Rest();
        }
    }

    // 구슬 first ~ first+orbCount-1 을 start에서 사방으로 (age초 동안 날아간 거리만큼)
    void MoveWave(int first, Vector2 start, float age, float offset)
    {
        float dist = age * orbSpeed;
        for (int i = 0; i < orbCount; i++)
        {
            GameObject orb = GameObject.Find("구슬 " + (first + i));
            if (!orb.activeSelf)
            {
                continue;
            }
            float angle = offset + i * Mathf.PI * 2f / orbCount;
            Vector2 p = start + new Vector2(Mathf.Cos(angle), Mathf.Sin(angle)) * dist;
            orb.transform.position = p;
            if (Vector2.Distance(p, hero.position) < 0.5f)
            {
                hero.TakeDamage(orbDamage);
                orb.SetActive(false);
            }
        }
    }

    // ---------- 패턴 4 · 바닥 폭발 (경고 발판) ----------
    void StartPanels()
    {
        state = 7;
        timer = Warn(panelWarn);
        panelUsed = phase == 2 ? panelCount + 3 : panelCount;
        for (int i = 1; i <= 9; i++)
        {
            GameObject panel = GameObject.Find("경고 발판 " + i);
            if (i > panelUsed)
            {
                panel.SetActive(false);
                continue;
            }
            // 첫 발판은 주인공 발밑, 나머지는 무대 안 아무 칸 (3×3칸이 벽을 넘지 않게)
            int cx = Mathf.RoundToInt(hero.position.x);
            int cy = Mathf.RoundToInt(hero.position.y);
            if (i > 1)
            {
                cx = Random.Range(3, 17);
                cy = Random.Range(4, 12);
            }
            panel.SetActive(true);
            panel.transform.localScale = new Vector3(3, 3, 1);
            // 스프라이트는 아래쪽 가운데를 기준으로 3배 커지므로, 가운데가 (cx, cy) 칸에 오도록 y를 1칸 아래에 둬요
            panel.transform.position = new Vector2(cx, cy + 1);
        }
        Callout("⚠ 바닥 폭발");
    }

    void PanelUpdate()
    {
        // 마지막 0.4초는 깜빡여서 「곧 터진다」를 알려요
        bool blink = timer < 0.4f && Mathf.FloorToInt(timer * 12f) % 2 == 0;
        for (int i = 1; i <= panelUsed; i++)
        {
            GameObject.Find("경고 발판 " + i).SetActive(!blink);
        }
        if (timer > 0f)
        {
            return;
        }
        // 터짐: 발판(가운데 ± 1.5칸) 안에 있으면 맞아요
        Shake(0.35f);
        bool hit = false;
        for (int i = 1; i <= panelUsed; i++)
        {
            GameObject panel = GameObject.Find("경고 발판 " + i);
            panel.SetActive(false);
            Vector2 c = panel.transform.position;
            if (Mathf.Abs(hero.position.x - c.x) < 1.5f && Mathf.Abs(hero.position.y - (c.y - 1f)) < 1.5f)
            {
                hit = true;
            }
        }
        if (hit)
        {
            hero.TakeDamage(panelDamage);
            Debug.Log("바닥 폭발 명중!");
        }
        Rest();
    }

    // ---------- 맞았을 때 · 2페이즈 · 쓰러짐 ----------
    void OnHit()
    {
        if (state == 0 || state == 6)
        {
            return;
        }
        hp -= 1;
        Sfx("타격");
        flash.SetActive(true);      // 하얀 번쩍임
        flashTimer = 0.08f;
        UpdateBar();
        if (hp <= 0)
        {
            Defeated();
        }
    }

    void EnterPhase2()
    {
        phase = 2;
        UIScreen.SetText("보스 UI", "페이즈", "2 페이즈 · 분노");
        UIScreen.SetColor("보스 UI", "페이즈", "#ff6b81");
        Message.Show("그림자 슬라임 왕이 분노했다!", 1.8f);
        Sfx("포효");
        Debug.Log("2페이즈 시작");
        Shake(0.4f);
    }

    void Defeated()
    {
        state = 6;
        timer = 1.0f;
        HideWarnings();
        HideOrbs();
        bodyBox.SetActive(false);
        UIScreen.Hide("보스 UI");
        Message.Show("그림자 슬라임 왕을 쓰러뜨렸다!", 2f);
        Sfx("승리 팡파르");
        Debug.Log("보스 토벌!");
        Shake(0.6f);
    }

    void DeathUpdate()
    {
        timer -= Time.deltaTime;
        rageVolume.weight = Mathf.MoveTowards(rageVolume.weight, 0f, Time.deltaTime);
        winVolume.weight = Mathf.MoveTowards(winVolume.weight, 1f, Time.deltaTime * 0.6f);
        if (!winShown)
        {
            size = Mathf.MoveTowards(size, 0.1f, Time.deltaTime * 2.4f);    // 쪼그라들며 사라져요
            transform.localScale = new Vector3(size, size, 1);
        }
        if (timer <= 0f && !winShown)
        {
            winShown = true;
            transform.position = new Vector2(-100, -100);   // 무대 밖으로
            UIScreen.Show("승리");
        }
    }

    // ---------- 화면 연출 ----------
    void Effects()
    {
        if (flashTimer > 0f)
        {
            flashTimer -= Time.deltaTime;
            if (flashTimer <= 0f)
            {
                flash.SetActive(false);
            }
        }
        // 주인공이 맞으면 「피격 볼륨」을 잠깐 켰다가 서서히 꺼요
        if (hero.hp < lastHeroHp)
        {
            hurtFlash = 1f;
            Shake(0.2f);
        }
        lastHeroHp = hero.hp;
        hurtFlash = Mathf.MoveTowards(hurtFlash, 0f, Time.deltaTime * 2.5f);
        hurtVolume.weight = hurtFlash;
        if (phase == 2 && state != 6)
        {
            rageVolume.weight = Mathf.MoveTowards(rageVolume.weight, 1f, Time.deltaTime * 0.8f);
        }

        // 화면 흔들기: 고정 카메라를 제자리 둘레로 살짝
        if (shakeTimer > 0f)
        {
            shakeTimer -= Time.deltaTime;
            Transform cam = Camera.main.transform;
            Vector2 jitter = new Vector2(Random.Range(-0.12f, 0.12f), Random.Range(-0.12f, 0.12f));
            cam.position = camHome + jitter;
            if (shakeTimer <= 0f)
            {
                cam.position = camHome;
            }
        }

        // H: 히트박스 보기 — 몸통 판정 범위를 원으로 보여 줘요
        if (Input.GetKeyDown(KeyCode.H))
        {
            showHitbox = !showHitbox;
            bodyBox.SetActive(showHitbox && state != 6);
            heroBox.SetActive(showHitbox);
            Debug.Log("히트박스 보기: " + (showHitbox ? "켬" : "끔"));
        }
    }

    void Shake(float seconds)
    {
        Sfx("쿵");                                  // 화면이 흔들릴 때마다 쿵!
        if (seconds > shakeTimer)
        {
            shakeTimer = seconds;
        }
    }

    void Callout(string text)
    {
        UIScreen.SetText("보스 UI", "패턴", text);
    }

    void UpdateBar()
    {
        UIScreen.SetValue("보스 UI", "체력 바", hp * 1f / maxHp);
        UIScreen.SetText("보스 UI", "체력 숫자", hp + " / " + maxHp);
    }

    void HideWarnings()
    {
        warnRing.SetActive(false);
        warnFill.SetActive(false);
        warnLine.SetActive(false);
        for (int i = 1; i <= 9; i++)
        {
            GameObject.Find("경고 발판 " + i).SetActive(false);
        }
    }

    void HideOrbs()
    {
        for (int i = 1; i <= orbCount * 2; i++)
        {
            GameObject.Find("구슬 " + i).SetActive(false);
        }
    }

    // ▼ 직접 만든 메서드: 씬의 「효과음」 오브젝트에 붙은 오디오 소스로 이름이 같은 오디오 클립을 겹쳐 재생해요
    //   PlayOneShot("클립 이름")은 지금 나는 소리를 끊지 않고 하나 더 겹쳐서 틀어요
    void Sfx(string clip)
    {
        GameObject.Find("효과음").GetComponent<AudioSource>().PlayOneShot(clip);
    }
}

using UnityEngine;

// 기사단장: 말을 걸면 NPC 컴포넌트의 대사를 들려주고,
